const __pageData = JSON.parse('{"title":"Week 1 solutions — spoilers","description":"","frontmatter":{"search":false,"prev":false,"next":false},"headers":[],"relativePath":"solutions/week-01.md","filePath":"solutions/week-01.md"}');
